import React, { useContext, useState, useMemo, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { ProductsContext } from '../context/ProductsContext';
import { AuthContext } from '../context/AuthContext';
import { db } from '../services/firebase';
import { ref, push, update, remove } from 'firebase/database';
import { FiEdit, FiTrash2, FiHome, FiLogOut, FiPercent, FiStar } from 'react-icons/fi';
import toast from 'react-hot-toast';
import './Admin.css';

const Admin = () => {
  const { products, promo, updatePromo } = useContext(ProductsContext);
  const { logout } = useContext(AuthContext);
  const [activeTab, setActiveTab] = useState('products'); // 'products' или 'promo'

  // Состояние для формы товара
  const [productForm, setProductForm] = useState({
    name: '',
    price: '',
    oldPrice: '',
    category: 'Букеты',
    isHit: false,
    image: null,
    imageUrl: ''
  });
  const [editingId, setEditingId] = useState(null);
  const [uploading, setUploading] = useState(false);

  // Состояние для формы акции
  const [promoForm, setPromoForm] = useState({
    bannerText: promo?.bannerText || 'Скидка 20% на первый заказ!',
    bannerEnabled: promo?.bannerEnabled ?? true,
    promoEndDate: promo?.promoEndDate ? new Date(promo.promoEndDate).toISOString().slice(0, 16) : '',
    firstOrderDiscount: promo?.firstOrderDiscount || 20
  });

  const IMGBB_API_KEY = '96f87f008c76df2e3346a979dbd12354';

  // Статистика товаров
  const stats = useMemo(() => {
    const total = products.length;
    const categories = products.reduce((acc, p) => {
      acc[p.category] = (acc[p.category] || 0) + 1;
      return acc;
    }, {});
    return { total, categories };
  }, [products]);

  const uploadImageToImgBB = async (file) => {
    const formData = new FormData();
    formData.append('image', file);
    const response = await fetch(`https://api.imgbb.com/1/upload?key=${IMGBB_API_KEY}`, {
      method: 'POST',
      body: formData
    });
    if (!response.ok) throw new Error('Ошибка загрузки на ImgBB');
    const data = await response.json();
    return data.data.url;
  };

  const resetProductForm = () => {
    setProductForm({
      name: '',
      price: '',
      oldPrice: '',
      category: 'Букеты',
      isHit: false,
      image: null,
      imageUrl: ''
    });
    setEditingId(null);
  };

  const handleProductSubmit = async (e) => {
    e.preventDefault();
    if (!productForm.name || !productForm.price) {
      toast.error('Заполните название и цену!');
      return;
    }

    setUploading(true);
    try {
      let imageUrl = productForm.imageUrl;
      if (productForm.image) {
        imageUrl = await uploadImageToImgBB(productForm.image);
      }

      const productData = {
        name: productForm.name,
        price: Number(productForm.price),
        oldPrice: productForm.oldPrice ? Number(productForm.oldPrice) : null,
        category: productForm.category,
        isHit: productForm.isHit,
        imageUrl: imageUrl || 'https://via.placeholder.com/300'
      };

      if (editingId) {
        await update(ref(db, `products/${editingId}`), productData);
        toast.success('✅ Товар обновлён');
      } else {
        await push(ref(db, 'products'), productData);
        toast.success('✅ Товар добавлен');
      }
      resetProductForm();
    } catch (error) {
      console.error('Ошибка:', error);
      toast.error('❌ Ошибка при сохранении');
    } finally {
      setUploading(false);
    }
  };

  const handleEdit = (product) => {
    setProductForm({
      name: product.name,
      price: product.price,
      oldPrice: product.oldPrice || '',
      category: product.category,
      isHit: product.isHit || false,
      image: null,
      imageUrl: product.imageUrl
    });
    setEditingId(product.id);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить этот товар?')) {
      await remove(ref(db, `products/${id}`));
      toast.success('🗑 Товар удалён');
    }
  };

  const handlePromoSubmit = async (e) => {
    e.preventDefault();
    try {
      const promoData = {
        bannerText: promoForm.bannerText,
        bannerEnabled: promoForm.bannerEnabled,
        promoEndDate: promoForm.promoEndDate ? new Date(promoForm.promoEndDate).getTime() : null,
        firstOrderDiscount: Number(promoForm.firstOrderDiscount)
      };
      await updatePromo(promoData);
      toast.success('✅ Настройки акции сохранены');
    } catch (error) {
      toast.error('❌ Ошибка сохранения');
    }
  };

  const handleLogout = async () => {
    await logout();
    toast.success('👋 До свидания!');
  };

  return (
    <div className="admin-page">
      <nav className="admin-navbar">
        <div className="admin-navbar-left">
          <Link to="/" className="admin-logo">🌸 Flower Shop</Link>
          <span className="admin-badge">Админ-панель</span>
        </div>
        <div className="admin-navbar-right">
          <Link to="/" className="admin-nav-link"><FiHome /> На сайт</Link>
          <button onClick={handleLogout} className="admin-logout-btn"><FiLogOut /> Выйти</button>
        </div>
      </nav>

      <div className="admin-container">
        <div className="admin-tabs">
          <button
            className={`tab-btn ${activeTab === 'products' ? 'active' : ''}`}
            onClick={() => setActiveTab('products')}
          >
            📦 Товары
          </button>
          <button
            className={`tab-btn ${activeTab === 'promo' ? 'active' : ''}`}
            onClick={() => setActiveTab('promo')}
          >
            🎯 Акции
          </button>
        </div>

        {activeTab === 'products' ? (
          <>
            <div className="admin-header">
              <h2>Управление товарами</h2>
            </div>

            <div className="admin-stats">
              <div className="stat-card">
                <span className="stat-number">{stats.total}</span>
                <span className="stat-label">Всего товаров</span>
              </div>
              {Object.entries(stats.categories).map(([cat, count]) => (
                <div key={cat} className="stat-card">
                  <span className="stat-number">{count}</span>
                  <span className="stat-label">{cat}</span>
                </div>
              ))}
            </div>

            <form onSubmit={handleProductSubmit} className="product-form">
              <h3>{editingId ? '✏️ Редактировать товар' : '➕ Добавить новый товар'}</h3>

              <div className="form-group">
                <label>Название букета *</label>
                <input
                  type="text"
                  value={productForm.name}
                  onChange={(e) => setProductForm({...productForm, name: e.target.value})}
                  placeholder="Например: Букет из 101 розы"
                  required
                />
              </div>

              <div className="form-row">
                <div className="form-group half">
                  <label>Цена (тенге) *</label>
                  <input
                    type="number"
                    value={productForm.price}
                    onChange={(e) => setProductForm({...productForm, price: e.target.value})}
                    placeholder="15000"
                    required
                  />
                </div>
                <div className="form-group half">
                  <label>Старая цена (если скидка)</label>
                  <input
                    type="number"
                    value={productForm.oldPrice}
                    onChange={(e) => setProductForm({...productForm, oldPrice: e.target.value})}
                    placeholder="20000"
                  />
                </div>
              </div>

              <div className="form-group">
                <label>Категория</label>
                <select
                  value={productForm.category}
                  onChange={(e) => setProductForm({...productForm, category: e.target.value})}
                >
                  <option value="Букеты">Букеты</option>
                  <option value="Комнатные">Комнатные растения</option>
                  <option value="Подарки">Подарки</option>
                  <option value="Свадебные">Свадебные букеты</option>
                </select>
              </div>

              <div className="form-group checkbox">
                <label>
                  <input
                    type="checkbox"
                    checked={productForm.isHit}
                    onChange={(e) => setProductForm({...productForm, isHit: e.target.checked})}
                  />
                  <FiStar /> Хит продаж
                </label>
              </div>

              <div className="form-group">
                <label>Фото товара</label>
                <input
                  type="file"
                  accept="image/*"
                  onChange={(e) => setProductForm({...productForm, image: e.target.files[0]})}
                />
                {productForm.imageUrl && !productForm.image && (
                  <div className="preview">
                    <img src={productForm.imageUrl} alt="preview" />
                  </div>
                )}
              </div>

              <div className="form-buttons">
                <button type="submit" disabled={uploading} className="submit-btn">
                  {uploading ? '⏳ Загрузка...' : (editingId ? '💾 Сохранить' : '➕ Добавить товар')}
                </button>
                {editingId && (
                  <button type="button" onClick={resetProductForm} className="cancel-btn">
                    ❌ Отмена
                  </button>
                )}
              </div>
            </form>

            <div className="products-list">
              <h3>📦 Существующие товары</h3>
              {products.length === 0 ? (
                <p className="empty-message">Товаров пока нет. Добавьте первый!</p>
              ) : (
                <div className="products-table">
                  {products.map(product => (
                    <div key={product.id} className="product-row">
                      <img src={product.imageUrl || 'https://via.placeholder.com/50'} alt={product.name} />
                      <div className="product-info">
                        <div className="product-name">
                          {product.name}
                          {product.isHit && <span className="hit-badge">🔥 Хит</span>}
                        </div>
                        <div className="product-price">
                          {product.oldPrice ? (
                            <>
                              <span className="old-price">{product.oldPrice.toLocaleString()} ₸</span>
                              <span className="new-price">{product.price.toLocaleString()} ₸</span>
                              <span className="discount-badge">
                                -{Math.round((1 - product.price / product.oldPrice) * 100)}%
                              </span>
                            </>
                          ) : (
                            <span>{product.price.toLocaleString()} ₸</span>
                          )}
                        </div>
                        <div className="product-category">{product.category}</div>
                      </div>
                      <div className="row-actions">
                        <button onClick={() => handleEdit(product)} className="edit-btn" title="Редактировать">
                          <FiEdit />
                        </button>
                        <button onClick={() => handleDelete(product.id)} className="delete-btn" title="Удалить">
                          <FiTrash2 />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </>
        ) : (
          <>
            <div className="admin-header">
              <h2>Управление акциями</h2>
            </div>

            <form onSubmit={handlePromoSubmit} className="promo-form">
              <div className="form-group">
                <label>Текст уведомления</label>
                <input
                  type="text"
                  value={promoForm.bannerText}
                  onChange={(e) => setPromoForm({...promoForm, bannerText: e.target.value})}
                  placeholder="Например: Скидка 20% на первый заказ!"
                />
              </div>

              <div className="form-group checkbox">
                <label>
                  <input
                    type="checkbox"
                    checked={promoForm.bannerEnabled}
                    onChange={(e) => setPromoForm({...promoForm, bannerEnabled: e.target.checked})}
                  />
                  Показывать всплывающее уведомление о скидке
                </label>
              </div>

              <div className="form-group">
                <label>Скидка на первый заказ (%)</label>
                <input
                  type="number"
                  min="0"
                  max="100"
                  value={promoForm.firstOrderDiscount}
                  onChange={(e) => setPromoForm({...promoForm, firstOrderDiscount: e.target.value})}
                />
              </div>

              <div className="form-group">
                <label>Дата окончания акции (для таймера)</label>
                <input
                  type="datetime-local"
                  value={promoForm.promoEndDate}
                  onChange={(e) => setPromoForm({...promoForm, promoEndDate: e.target.value})}
                />
                <small>Оставьте пустым, если акция бессрочная</small>
              </div>

              <div className="form-buttons">
                <button type="submit" className="submit-btn">
                  💾 Сохранить настройки
                </button>
              </div>
            </form>

            <div className="banner-preview">
              <h4>Предпросмотр контента:</h4>
              <div className={`promo-banner ${promoForm.bannerEnabled ? '' : 'disabled'}`}>
                <div className="banner-content">
                  <FiPercent className="banner-icon" />
                  <span className="banner-text">{promoForm.bannerText}</span>
                  {promoForm.promoEndDate && (
                    <div className="banner-timer">
                      ⏰ До окончания: <CountdownTimer endDate={new Date(promoForm.promoEndDate).getTime()} />
                    </div>
                  )}
                </div>
              </div>
              <p style={{marginTop: '10px', fontSize: '0.8rem', color: '#666'}}>
                * Это визуальная демонстрация текста. На сайте это будет выглядеть как всплывающий попап.
              </p>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

const CountdownTimer = ({ endDate }) => {
  const [timeLeft, setTimeLeft] = useState(calculateTimeLeft());

  function calculateTimeLeft() {
    const difference = endDate - Date.now();
    if (difference <= 0) return null;
    return {
      days: Math.floor(difference / (1000 * 60 * 60 * 24)),
      hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
      minutes: Math.floor((difference / 1000 / 60) % 60),
      seconds: Math.floor((difference / 1000) % 60)
    };
  }

 useEffect(() => {
  const timer = setInterval(() => {
    setTimeLeft(calculateTimeLeft());
  }, 1000);
  return () => clearInterval(timer);
}, [calculateTimeLeft]);

  if (!timeLeft) return <span>Акция завершена</span>;

  return (
    <span className="timer">
      {timeLeft.days > 0 && `${timeLeft.days}д `}
      {timeLeft.hours}ч {timeLeft.minutes}м {timeLeft.seconds}с
    </span>
  );
};

export default Admin;